import{I as e,b as a,c as r,O as d}from"./chunks/framework.BGwiwaG1-ghp20261122.js";const g=JSON.parse('{"title":"暗夜之影／午夜魅影活动攻略","description":"少女回战 2026 年 11 月第 29 期弹珠活动。查看日服暗夜之影和繁中服午夜魅影的开放时段、现在·幽灵再现碎片、三件新宝物和兑换条件。","frontmatter":{"title":"暗夜之影／午夜魅影活动攻略","description":"少女回战 2026 年 11 月第 29 期弹珠活动。查看日服暗夜之影和繁中服午夜魅影的开放时段、现在·幽灵再现碎片、三件新宝物和兑换条件。","breadcrumbLabel":"暗夜之影／午夜魅影","breadcrumbs":[["/events/","限时活动"]],"socialImage":"/images/ghost-return/event-banner.webp","lastmod":"2026-11-20"},"headers":[],"relativePath":"events/dark-shadow/index.md","filePath":"events/dark-shadow/index.md"}'),h={name:"events/dark-shadow/index.md"};function s(l,t,i,n,o,b){return a(),r("div",null,[...t[0]||(t[0]=[d('<article class="page-shell knowledge-page reference-guide"><h1 id="暗夜之影-午夜魅影" tabindex="-1">暗夜之影／午夜魅影 <a class="header-anchor" href="#暗夜之影-午夜魅影" aria-label="Permalink to &quot;暗夜之影／午夜魅影&quot;">​</a></h1><p>「暗夜之影」是日服《少女廻戦》2026 年 11 月的第 29 期弹珠活动，原名「闇夜の影」，繁中服名为「午夜魅影」。主会场包含活跃任务、剧情、秘宝、特卖和兑换。弹珠奖励可开出「现在·幽灵再现」的碎片。</p><img src="/images/ghost-return/event-banner.webp" alt="暗夜之影与午夜魅影的原版弹珠活动横幅" width="928" height="300"><h2 id="两服时间" tabindex="-1">两服时间 <a class="header-anchor" href="#两服时间" aria-label="Permalink to &quot;两服时间&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区服</th><th>弹珠排行</th><th>日常任务钢珠券</th></tr></thead><tbody><tr><td>日服 · 日本时间</td><td>2026-11-19 11:10 至 2026-11-25 23:59:59</td><td>2026-11-20 00:00 至 2026-11-25 23:59:59</td></tr><tr><td>繁中服 · 台港澳时间</td><td>2026-11-20 10:40 至 2026-11-26 23:59:59</td><td>2026-11-21 00:00 至 2026-11-26 23:59:59</td></tr></tbody></table><p>表内时段来自各服客户端的弹珠排行与日常产出配置。 <a href="/events/#current">本期活动</a></p><h2 id="弹珠怎么玩" tabindex="-1">弹珠怎么玩 <a class="header-anchor" href="#弹珠怎么玩" aria-label="Permalink to &quot;弹珠怎么玩&quot;">​</a></h2><p>每次购买普通钢珠消耗 5 张钢珠券，购买双倍对应玩法需 5 张双倍钢珠券。发射后领取命中袋子的奖励。连续 7 次摇奖未中奖时，补偿 5 张双倍钢珠券。购买钢珠用的券与兑换用的活动奖券是两种道具。</p><h2 id="hero-shards" tabindex="-1">现在·幽灵再现碎片 <a class="header-anchor" href="#hero-shards" aria-label="Permalink to &quot;现在·幽灵再现碎片 {#hero-shards}&quot;">​</a></h2><ul><li>弹珠命中对应袋子可获得武将限定礼盒，打开后可选择 2 枚碎片。</li><li>秘宝第二进阶档的第 2 档给 20 个武将自选礼盒，每个可选 2 枚该武将碎片。</li><li>合成「现在·幽灵再现」需要 180 枚。 <a href="/heroes/603680">武将详情</a> · <a href="/art-library/?asset=hero-603680">查看原版立绘</a></li></ul><h2 id="rewards" tabindex="-1">活跃与累计奖励 <a class="header-anchor" href="#rewards" aria-label="Permalink to &quot;活跃与累计奖励 {#rewards}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>活跃度</th><th style="text-align:right;">钢珠券</th><th style="text-align:right;">摄像机碎片</th><th>其他奖励</th></tr></thead><tbody><tr><td>20</td><td style="text-align:right;">2</td><td style="text-align:right;">30</td><td>—</td></tr><tr><td>60</td><td style="text-align:right;">2</td><td style="text-align:right;">20</td><td>—</td></tr><tr><td>100</td><td style="text-align:right;">3</td><td style="text-align:right;">20</td><td>—</td></tr><tr><td>150</td><td style="text-align:right;">4</td><td style="text-align:right;">20</td><td>—</td></tr><tr><td>200</td><td style="text-align:right;">—</td><td style="text-align:right;">—</td><td>双倍钢珠券 ×5、英魂自选礼包 ×1</td></tr></tbody></table><p>弹珠累计达到 90、210、300 时，每档还可再获得偷拍摄像机碎片 ×30。 <a href="/bonds/treasures/700934/">偷拍摄像机详情</a></p><h2 id="exchange" tabindex="-1">新宝物与兑换 <a class="header-anchor" href="#exchange" aria-label="Permalink to &quot;新宝物与兑换 {#exchange}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝物</th><th>获取方式</th><th>10 星全体武将加成</th></tr></thead><tbody><tr><td><a href="/bonds/treasures/700934/">偷拍摄像机</a></td><td>活跃与累计奖励可拿碎片。兑换第 3 阶段用 40 张活动奖券换碎片 ×60，限 6 次</td><td>生命值 +9.00%、力量 +3,100</td></tr><tr><td><a href="/bonds/treasures/703680/">水果手机</a></td><td>立绘手机可领本体。兑换第 2 阶段用 40 张活动奖券换碎片 ×60，限 7 次</td><td>生命值 +9.00%</td></tr><tr><td><a href="/bonds/treasures/700935/">高定高跟鞋</a></td><td>特卖纪念礼盒Ⅱ中自选本体</td><td>攻击力 +3.00%、会心一击伤害 +3.00%</td></tr></tbody></table><p>兑换第 2、3 阶段分别需要上一阶段的兑换进度达到 1 次。繁中服兑换货币原名「午夜魅影獎券」。</p><h3 id="heels" tabindex="-1">高定高跟鞋礼包 <a class="header-anchor" href="#heels" aria-label="Permalink to &quot;高定高跟鞋礼包 {#heels}&quot;">​</a></h3><p>日服特卖的「闇夜の影特売品記念」与繁中服的「午夜魅影大暴走紀念」均包含对应纪念礼盒Ⅱ。打开礼盒，从奖励选项中选择高定高跟鞋本体 ×1。 <a href="/bonds/treasures/700935/">高定高跟鞋详情</a></p><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><p>活动入口、奖励及排期按 2026 年 11 月官方客户端记录核对。 <a href="https://shupdate.menaapp.net/updatePackage/android/0.821/0_821_6/versions.csv" target="_blank" rel="noreferrer">日服 0.821.6 客户端清单</a> · <a href="https://shtwnupdate.menaapp.net/updatePackage/android/0.840/0_840_61/versions.csv" target="_blank" rel="noreferrer">繁中服 0.840.61 客户端清单</a></p></article>',1)])])}const p=e(h,[["render",s]]);export{g as __pageData,p as default};
